using System.Text.Json;
using System.Text.Json.Nodes;

namespace FindRomCover.Services.Ai;

/// <summary>
///     Parses and applies user-supplied JSON parameters to AI provider request bodies.
///     The JSON object is merged recursively into the body generated by each provider
///     adapter, so users can tune things such as temperature, token limits, and
///     provider-specific options without changing the application.
/// </summary>
internal static class AiRequestParameters
{
    /// <summary>
    ///     Maximum accepted length of the custom parameter JSON, in characters.
    /// </summary>
    internal const int MaxJsonLength = 16 * 1024;

    /// <summary>
    ///     Keys generated by the application that cannot be overridden because doing so
    ///     would break prompts, image payloads, or response parsing.
    /// </summary>
    private static readonly HashSet<string> ReservedKeys = new(StringComparer.OrdinalIgnoreCase)
    {
        "model",
        "messages",
        "contents",
        "system",
        "systemInstruction",
        "stream"
    };

    /// <summary>
    ///     Validates custom request parameters.
    /// </summary>
    /// <param name="json">The JSON supplied in AI settings; empty means no overrides.</param>
    /// <param name="parameters">The parsed JSON object when validation succeeds.</param>
    /// <param name="error">A user-facing validation error, or <see langword="null"/>.</param>
    /// <returns><see langword="true"/> when the value is empty or a valid JSON object.</returns>
    internal static bool TryParse(string? json, out JsonObject? parameters, out string? error)
    {
        parameters = null;
        error = null;

        if (!TryParseObject(json, out var parsed, out error)) return false;
        if (parsed is null) return true;

        var reservedKey = parsed
            .Select(static pair => pair.Key)
            .FirstOrDefault(ReservedKeys.Contains);

        if (reservedKey is not null)
        {
            error = $"The key '{reservedKey}' is managed by FindRomCover and cannot be overridden. " +
                    "Remove it from the custom request parameters.";
            return false;
        }

        parameters = parsed;
        return true;
    }

    private static bool TryParseObject(string? json, out JsonObject? parameters, out string? error)
    {
        parameters = null;
        error = null;

        if (string.IsNullOrWhiteSpace(json)) return true;

        if (json.Length > MaxJsonLength)
        {
            error = $"The custom request parameters are too large (maximum {MaxJsonLength:N0} characters).";
            return false;
        }

        try
        {
            if (JsonNode.Parse(json) is not JsonObject parsed)
            {
                error = "The custom request parameters must be a JSON object, for example {\"temperature\": 0.2}.";
                return false;
            }

            parameters = parsed;
            return true;
        }
        catch (JsonException ex)
        {
            error = $"The custom request parameters are not valid JSON: {ex.Message}";
            return false;
        }
        catch (ArgumentException ex)
        {
            // JsonObject rejects duplicate property names with an ArgumentException.
            error = $"The custom request parameters are not valid JSON: {ex.Message}";
            return false;
        }
    }

    /// <summary>
    ///     Merges custom request parameters into a serialized provider request body.
    ///     Invalid or reserved keys are ignored and logged so a hand-edited settings file
    ///     cannot break AI requests.
    /// </summary>
    /// <param name="baseJson">The provider request body generated by the application.</param>
    /// <param name="customJson">The custom JSON object from AI settings.</param>
    /// <returns>The merged request body, or <paramref name="baseJson"/> when there is nothing to apply.</returns>
    internal static string ApplyToJson(string baseJson, string? customJson)
    {
        if (string.IsNullOrWhiteSpace(customJson)) return baseJson;

        if (!TryParseObject(customJson, out var parameters, out var error) || parameters is null)
        {
            LogService.WarningTransient($"Ignoring invalid custom AI request parameters: {error}");
            return baseJson;
        }

        try
        {
            if (JsonNode.Parse(baseJson) is not JsonObject payload) return baseJson;

            Merge(payload, parameters);
            return payload.ToJsonString();
        }
        catch (JsonException ex)
        {
            LogService.WarningTransient(ex, "Could not apply the custom AI request parameters.");
            return baseJson;
        }
    }

    private static void Merge(JsonObject target, JsonObject overrides)
    {
        foreach (var (key, value) in overrides)
        {
            if (ReservedKeys.Contains(key)) continue;

            if (value is null)
            {
                // A null override removes a default field, which is useful for providers
                // that reject parameters the application normally sends.
                target.Remove(key);
                continue;
            }

            if (value is JsonObject overrideObject && target[key] is JsonObject targetObject)
            {
                Merge(targetObject, overrideObject);
                continue;
            }

            target[key] = value.DeepClone();
        }
    }
}
